<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Models\MarketingVideoFilm;
use App\Services\Marketing\{MarketingClipSource,MarketingPackagingAssets,MarketingFilmPackaging,MarketingWorkspaceFilm};
use Illuminate\Http\Request;
class MarketingPackagingController extends Controller {
 private function project(Request $r,string $id){return app(MarketingClipSource::class)->project($id,(int)$r->user()?->id);}
 public function config(Request $r,string $project,string $film){
  $p=$this->project($r,$project);$f=MarketingVideoFilm::where('project_id',$p->id)->where('owner_id',$p->owner_id)->where('status','completed')->findOrFail($film);
  $service=app(MarketingFilmPackaging::class);$content=app(MarketingClipSource::class)->readSnapshot(fn()=>$service->replacementSource($f));$a=app(MarketingPackagingAssets::class);
  try{$brand=$a->brand($p);$brandData=['name'=>$brand['name'],'available'=>true,'sha256'=>$brand['sha256'],'url'=>route('marketing.workspace.packaging.image',[$project,'brand'])];}
  catch(\Symfony\Component\HttpKernel\Exception\HttpExceptionInterface){$brand=null;$brandData=['name'=>app(\App\Support\ShopBrand::class)->name(),'available'=>false,'sha256'=>null,'url'=>null];}
  $product=$a->product($p);$tracks=$a->catalogue($p,$f->input['settings']['track']??null);$settings=$f->input['settings']??['enabled'=>false,'template'=>'minimal','duration'=>3,'company'=>$brandData['name'],'cta'=>$content->input['cta'],'track'=>null,'volume'=>18,'duck'=>true,'fade'=>true,'logo_sha256'=>$brandData['sha256']];
  $settings['logo_sha256']=$brandData['sha256'];if(!$brand)$settings['enabled']=false;
  if($settings['track']&&!in_array($settings['track'],array_column($tracks,'id'),true))$settings['track']=null;
  return response()->json(['speed'=>$f->input['speed']??null,'source_duration'=>$content->input['duration'],'overlays'=>$f->input['overlays']??[],'overlay_images'=>app(\App\Services\Marketing\MarketingOverlays::class)->catalogue($p),'overlay_upload_url'=>route('marketing.workspace.packaging.overlay-upload',$project),'emphasis'=>$f->input['emphasis']??[],'framing'=>$f->input['framing']??[],'visual_recipe'=>app(\App\Services\Marketing\MarketingVisualRecipe::class)->resolve($f),'information_cards'=>$f->input['information_cards']??[],'subtitles'=>app(\App\Services\Marketing\MarketingSubtitleService::class)->config($f),'film_id'=>$f->id,'hash'=>$f->output_sha256,'content_duration'=>$content->input['duration'],'content_url'=>route('marketing.workspace.films.preview',[$project,$content->id]),'brand'=>$brandData,'product_url'=>$product?route('marketing.workspace.packaging.image',[$project,'product']):null,'tracks'=>$tracks,'settings'=>$settings,'apply_url'=>route('marketing.workspace.packaging.adopt',[$project,$film]),'upload_url'=>route('marketing.workspace.packaging.upload',$project),'internal'=>$a->internal()])->header('Cache-Control','private, no-store');
 }
 public function audio(Request $r,string $project,string $audio){$p=$this->project($r,$project);$a=app(MarketingPackagingAssets::class)->audio($p,$audio);return response()->file($a['path'],['Content-Type'=>$a['mime']??'audio/wav','Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
 public function image(Request $r,string $project,string $kind){$p=$this->project($r,$project);$a=app(MarketingPackagingAssets::class);$img=str_starts_with($kind,'overlay-')?app(\App\Services\Marketing\MarketingOverlays::class)->image($p,substr($kind,8)):($kind==='brand'?$a->brand($p):($kind==='product'?$a->product($p):null));abort_unless($img,404);return response()->file($img['path'],['Content-Type'=>$img['mime'],'Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff','Content-Security-Policy'=>"default-src 'none'; style-src 'unsafe-inline'; sandbox"]);}
 public function adopt(Request $r,string $project,string $film){$this->project($r,$project);$d=$r->validate(['request_id'=>'required|uuid','base_sha256'=>'required|regex:/^[a-f0-9]{64}$/','consent'=>'required|accepted','settings'=>'required|array','subtitle_settings'=>'sometimes|nullable|array','information_cards'=>'sometimes|array','framing'=>'sometimes|array','emphasis'=>'sometimes|array','overlays'=>'sometimes|array','speed'=>'sometimes|nullable|array']);$plan=null;if(isset($d['subtitle_settings'])){$base=MarketingVideoFilm::where('project_id',$project)->where('owner_id',$r->user()->id)->where('status','completed')->findOrFail($film);abort_unless(hash_equals($base->output_sha256??'',$d['base_sha256']),409,'基准成片已变化。');$plan=app(\App\Services\Marketing\MarketingSubtitleService::class)->plan($base,$d['subtitle_settings']);}$f=app(MarketingFilmPackaging::class)->prepare($project,$r->user()->id,$d['request_id'],$film,$d['base_sha256'],$d['settings'],$plan,$d['information_cards']??null,$d['framing']??null,$d['emphasis']??null,$d['overlays']??null,$d['speed']??null,array_key_exists('speed',$d));$url=route('marketing.workspace.show',['project'=>$project,'screen'=>'finished','film'=>$f->id]);return response()->json(['film_id'=>$f->id,'status'=>$f->status,'url'=>$url]);}
 public function overlayUpload(Request $r,string $project){$p=$this->project($r,$project);$r->validate(['file'=>'required|file|max:10240|mimetypes:image/jpeg,image/png,image/webp']);$file=$r->file('file');$size=@getimagesize($file->getRealPath());abort_unless($size&&$size[0]*$size[1]<=40000000,422,'图片尺寸过大或内容无效。');$mime=$file->getMimeType();$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime];$path=$file->storeAs('marketing-assets/'.$p->id.'/overlays',(string)\Illuminate\Support\Str::uuid().'.'.$ext,'local');$a=\App\Models\MarketingAsset::create(['project_id'=>$p->id,'name'=>mb_substr(basename($file->getClientOriginalName()),0,180),'path'=>$path,'mime'=>$mime,'size'=>$file->getSize(),'authorized'=>true]);return response()->json(['image'=>['id'=>$a->id,'name'=>$a->name,'ratio'=>$size[0]/$size[1],'url'=>route('marketing.workspace.packaging.image',[$project,'overlay-'.$a->id])]]);}
 public function upload(Request $r,string $project){
  $p=$this->project($r,$project);
  // finfo can report valid tagged MP3s as octet-stream; the service verifies and decodes the actual audio.
  $d=$r->validate(['file'=>'required|file|max:20480|extensions:mp3,wav,m4a,ogg','name'=>'nullable|string|max:100','source'=>'nullable|string|max:500','license_note'=>'nullable|string|max:1000'],['file.required'=>'请选择音频文件。','file.file'=>'音频文件未能上传，请重新选择。','file.max'=>'音频文件不能超过20MB。','file.extensions'=>'请选择MP3、WAV、M4A或OGG音频文件。']);
  $file=$r->file('file');$name=trim($d['name']??'')?:mb_substr(pathinfo($file->getClientOriginalName(),PATHINFO_FILENAME),0,100);
  $a=app(MarketingPackagingAssets::class)->upload($p,$file,$name?:'我的音乐',$d['source']??'',$d['license_note']??'');
  return response()->json(['id'=>$a->id,'track'=>app(MarketingPackagingAssets::class)->privateItem($p,$a)]);
 }
}
